import './cloud-sync.js';
import{MEASUREMENT_TRACKS,MEASUREMENT_CHAIN,MEASUREMENT_DIAGNOSTIC,recommendMeasurementTrack,convertMeasure,rectangleMeasures,createBlankMeasurementLearner}from'./measurement-data.js';

const $=s=>document.querySelector(s),storageKey='mathlab-measurement-v1',memory={};
function blankStore(){return{a:createBlankMeasurementLearner(),b:createBlankMeasurementLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankMeasurementLearner(),hintLevel=0,errors=0,sessionMissionId=null,work={};
function ensureState(){const blank=createBlankMeasurementLearner();state={...blank,...state,diagnostic:{...blank.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...blank.evidence,...state.evidence},family:{...blank.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return MEASUREMENT_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[MEASUREMENT_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{errors:0,hints:0,work:{}};errors=Number(saved.errors)||0;hintLevel=Number(saved.hints)||0;work=saved.work||{}}
function saveSession(nextWork=work){if(!sessionMissionId)return;work=nextWork;state.sessions[sessionMissionId]={errors,hints:hintLevel,work};save()}
function miss(message){errors++;saveSession();feedback(message,'try')}
function complete(i,dims=[],pending=false,preview=false){const m=MEASUREMENT_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,errors,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.explanation=state.evidence.explanation==='unknown'?'learning':state.evidence.explanation}if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];errors=0;hintLevel=0;work={};sessionMissionId=null;save();setTimeout(render,450)}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}
function mix(correct,others){const values=[...new Set([correct,...others])],shift=String(correct).length%values.length;return values.slice(shift).concat(values.slice(0,shift))}
function textChoices(correct,others,attr){return `<div class="answer-grid">${mix(correct,others).map(v=>`<button class="choice" data-${attr}="${v===correct?'correct':'wrong'}">${esc(v)}</button>`).join('')}</div>`}
function numberChoices(correct,others,attr){return `<div class="answer-grid number-choices">${mix(correct,others).map(v=>`<button class="choice" data-${attr}="${v}">${v}</button>`).join('')}</div>`}
function unitNames(p){return [p.answer,...p.decoys.map(x=>x.split(' ')[0].replace(/[.:]/g,'').toLowerCase())]}
function unitScene(p){const icon=p.answer==='gallons'?'🛁':p.answer==='feet'?'🏫':'✏️';return `<div class="unit-scene" role="img" aria-label="${esc(p.scenario)}"><span>${icon}</span><strong>${esc(p.scenario)}</strong><div class="ruler-line"><i></i><i></i><i></i><i></i><i></i><i></i></div></div>`}
function conversionModel(p){return `<div class="conversion-model"><div><small>START</small><strong>${p.amount}</strong></div><span>× ${p.factor}</span><div><small>NEW UNIT</small><strong>?</strong></div></div><p class="model-caption">The unit pieces get smaller, so the number of pieces gets larger. The actual length stays the same.</p>`}
function rectangleModel(m,mode='none'){const r=rectangleMeasures(m.drawingL,m.drawingW,m.scale),cells=Array.from({length:m.drawingL*m.drawingW},()=>`<i class="${mode==='surface'?'surface':''}"></i>`).join(''),scale=m.scale>1?`Plan: ${m.drawingL} cm × ${m.drawingW} cm · 1 cm = ${m.scale} ${m.unit}`:`Rectangle: ${m.drawingL} ${m.unit} × ${m.drawingW} ${m.unit}`,path=mode==='boundary'?`<div class="perimeter-path" aria-label="Perimeter path: ${r.length} plus ${r.width} plus ${r.length} plus ${r.width} ${m.unit}"><span class="perimeter-edge edge-top">${r.length}</span><span class="perimeter-edge edge-right">${r.width}</span><span class="perimeter-edge edge-bottom">${r.length}</span><span class="perimeter-edge edge-left">${r.width}</span></div>`:'';return `<div class="measure-stage"><p>${scale}</p><div class="measure-visual"><div class="measure-grid ${mode}" style="--measure-cols:${m.drawingL}" role="img" aria-label="${esc(scale)}">${cells}</div>${path}</div><div class="measure-dimensions"><span>real length <b>${r.length} ${m.unit}</b></span><span>real width <b>${r.width} ${m.unit}</b></span></div></div>`}
function pairText(r){return `Perimeter ${r.perimeter}; area ${r.area}`}

function renderDiagnostic(){const d=state.diagnostic;if(d.index>=MEASUREMENT_DIAGNOSTIC.length){state.track=state.track||recommendMeasurementTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful measurement challenges. It is not a grade label.</p><button class="primary" data-action="start">Choose a useful unit →</button></div>`;return}const q=MEASUREMENT_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/MEASUREMENT_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${MEASUREMENT_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Think about what the number would mean in real life.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'That measurement relationship is clear.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},500)})}
function renderUnit(){const p=track().unit;if(!work.unit){$('#activity').innerHTML=`<p class="eyebrow">USEFUL UNITS TELL A USEFUL STORY</p><h3>${esc(p.scenario)}</h3>${unitScene(p)}<p class="prompt">Which unit gives a sensible measurement?</p><div class="answer-grid">${mix(p.answer,unitNames(p).filter(x=>x!==p.answer)).map(v=>`<button class="choice" data-unit="${v}">${esc(v[0].toUpperCase()+v.slice(1))}</button>`).join('')}</div>${controls()}${hint('Choose a unit that matches both what is measured and its approximate size.')}`;document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{if(b.dataset.unit===p.answer){work={...work,unit:true};saveSession();feedback(`${p.answer} fits the object and gives a useful-sized number. Now explain why.`,'good');setTimeout(renderMission,350)}else miss('Imagine the likely number. Is this unit the right type and size?')})}else{$('#activity').innerHTML=`<p class="eyebrow">JUSTIFY THE UNIT</p><h3>Why are ${esc(p.answer)} useful here?</h3>${unitScene(p)}${textChoices(p.proof,p.decoys,'unit-proof')}${controls()}${hint('A strong reason mentions the object, the kind of measure, and the size of the unit.')}`;document.querySelectorAll('[data-unit-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.unitProof==='correct'){feedback('Yes. The unit matches the quantity and gives a useful number.','good');complete(1,['unit','explanation'])}else miss('The unit must match both the type of quantity and the object’s size.')})}}
function renderConversion(){const p=track().conversion;if(!work.answer){$('#activity').innerHTML=`<p class="eyebrow">SAME LENGTH · DIFFERENT UNIT PIECES</p><h3>${esc(p.prompt)}</h3>${conversionModel(p)}${numberChoices(p.answer,[p.amount+p.factor,p.amount],'conversion-answer')}${controls()}${hint(`There are ${p.factor} smaller units in each larger unit. Make ${p.amount} equal groups.`)}`;document.querySelectorAll('[data-conversion-answer]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.conversionAnswer);if(answer===p.answer&&convertMeasure(p.amount,p.factor)===answer){work={...work,answer:true};saveSession();feedback(`${p.answer} names the same length with smaller unit pieces. Now prove it.`,'good');setTimeout(renderMission,350)}else miss('The actual length cannot change. Count equal groups of the smaller unit.')})}else{$('#activity').innerHTML=`<p class="eyebrow">PROVE THE CONVERSION</p><h3>${esc(p.prompt.replace('?',String(p.answer)))}</h3>${textChoices(p.equation,p.decoys,'conversion-proof')}${controls()}${hint('Use the number of smaller units inside one larger unit as the group size.')}`;document.querySelectorAll('[data-conversion-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.conversionProof==='correct'){feedback('Correct. The number changes because the unit size changes; the measure does not.','good');complete(2,['conversion','explanation'])}else miss('Check whether the equation represents equal groups and preserves the original length.')})}}
function renderMeasure(){const p=track().measure,r=rectangleMeasures(p.drawingL,p.drawingW,p.scale),mode=work.mode||'none';if(!work.perimeter){$('#activity').innerHTML=`<p class="eyebrow">TRACE THE BOUNDARY</p><h3>How much length goes all the way around?</h3>${rectangleModel(p,mode)}<div class="answer-row"><button class="secondary" data-action="trace-boundary">Trace boundary</button><button class="secondary" data-action="cover-surface">Cover surface</button></div>${numberChoices(r.perimeter,[r.length+r.width,r.area],'perimeter-answer')}${controls()}${hint('Perimeter follows every outside side once. For a rectangle, both lengths and both widths are included.')}`;document.querySelectorAll('[data-perimeter-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.perimeterAnswer)===r.perimeter){work={...work,perimeter:true};saveSession();feedback(`${r.perimeter} ${p.unit} traces the complete boundary. Now cover the surface.`,'good');setTimeout(renderMission,350)}else miss('Walk around all four outside sides. Do not count the inside squares.')})}else if(!work.area){$('#activity').innerHTML=`<p class="eyebrow">COVER THE SURFACE</p><h3>How many square units cover the inside?</h3>${rectangleModel(p,'surface')}${numberChoices(r.area,[r.length+r.width,r.perimeter],'area-answer')}${controls()}${hint('Area counts rows of equal-sized squares: real length × real width.')}`;document.querySelectorAll('[data-area-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.areaAnswer)===r.area){work={...work,area:true};saveSession();feedback(`${r.area} square ${p.unit} covers the surface. Now prove why the two measures differ.`,'good');setTimeout(renderMission,350)}else miss('Count equal-sized square units, not the outside edge.')})}else{$('#activity').innerHTML=`<p class="eyebrow">CONNECT ACTION, NUMBER, AND UNIT</p><h3>Perimeter ${r.perimeter} ${p.unit} · area ${r.area} square ${p.unit}</h3>${rectangleModel(p,'surface')}${textChoices(p.proof,p.decoys,'measure-proof')}${controls()}${hint('A complete proof names the real side lengths, adds the four edges, multiplies rows by columns, and uses different units.')}`;document.querySelectorAll('[data-measure-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.measureProof==='correct'){feedback('Yes. Boundary length and covered surface answer different questions.','good');complete(3,['perimeterArea','explanation'],true)}else miss('Check the real dimensions, the operation, and whether the unit is linear or square.')})}}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the measurement steps have faded from memory.</strong><p>About ${hours} hours remain. Waiting checks whether Ella can rebuild the unit reasoning.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses a different conversion and design. It will not count as delayed evidence.</p></div>`;return}const p=ready?track().fresh.challenge:track().fresh.preview,c=p.conversion,r=rectangleMeasures(p.measure.drawingL,p.measure.drawingW,p.measure.scale);if(!work.conversion){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW DESIGN':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>${esc(c.prompt)}</h3>${conversionModel(c)}${numberChoices(c.answer,[c.amount+c.factor,c.amount*c.factor*2],'fresh-conversion')}${controls()}${hint(`Each larger unit contains ${c.factor} smaller units.`)}`;document.querySelectorAll('[data-fresh-conversion]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.freshConversion)===c.answer&&convertMeasure(c.amount,c.factor)===c.answer){work={...work,conversion:true};saveSession();feedback('The conversion preserves the measure. Now solve the new design.','good');setTimeout(renderMission,350)}else miss('Use equal groups of smaller units and keep the actual measure unchanged.')});return}if(!work.measure){const correct=pairText(r),others=[`Perimeter ${r.length+r.width}; area ${r.perimeter}`,`Perimeter ${r.area}; area ${r.perimeter}`];$('#activity').innerHTML=`<p class="eyebrow">NEW RECTANGLE OR SCALE DRAWING</p><h3>Find both boundary and surface.</h3>${rectangleModel(p.measure,'none')}${textChoices(correct,others,'fresh-measure')}${controls()}${hint('Apply the scale to each side first. Then calculate perimeter and area from the real dimensions.')}`;document.querySelectorAll('[data-fresh-measure]').forEach(b=>b.onclick=()=>{if(b.dataset.freshMeasure==='correct'){work={...work,measure:true};saveSession();feedback('Both measurements use the real dimensions. Now prove the conversion and the design.','good');setTimeout(renderMission,350)}else miss('Check the scale, all four boundary sides, the square-unit surface, and their units.')});return}$('#activity').innerHTML=`<p class="eyebrow">ONE PROOF FOR THE COMPLETE DESIGN</p><h3>${c.answer} smaller units · perimeter ${r.perimeter} · area ${r.area}</h3>${textChoices(p.proof,p.decoys,'fresh-proof')}${controls()}${hint('The proof must include the exact conversion, real side lengths, perimeter, area, and correct units.')}`;document.querySelectorAll('[data-fresh-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.freshProof==='correct'){feedback(ready?'You transferred the measurement ideas to a new design after a delay.':'Preview complete. Return later for fresh evidence.','good');complete(4,['conversion','perimeterArea','explanation'],false,!ready)}else miss('Reject any explanation that changes the measure, skips the scale, or swaps perimeter and area.')})}
function renderComplete(i){const m=MEASUREMENT_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=MEASUREMENT_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderUnit();else if(i===2)renderConversion();else if(i===3)renderMeasure();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=MEASUREMENT_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(MEASUREMENT_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankMeasurementLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const labels={unit:'Choose useful units',conversion:'Preserve measures',perimeterArea:'Boundary & surface',explanation:'Explain & transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['measurement-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='preview'){state.previewFresh=true;save();render()}else if(a==='trace-boundary'){work={...work,mode:'boundary'};saveSession();renderMission()}else if(a==='cover-surface'){work={...work,mode:'surface'};saveSession();renderMission()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankMeasurementLearner();sessionMissionId=null;ensureState();save();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the measurement and scale review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankMeasurementLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();
